        if (exists){
            exists.qty++;
        }else{
            cart.push({id:item.id, name:item.name, price:parseFloat(item.price), qty:1});
        }
        localStorage.setItem('cart', JSON.stringify(cart));
        updateCartCount();
    }

    function updateCartCount(){
